#include "xds_text.h"

#include <map>
#include <string.h>

// From xds_text_data.cpp (generated by tools/xdk/gen_text.py).
extern const int xdsExtraCount;
extern const unsigned short xdsExtraCodes[];
extern const unsigned char xdsExtraWidths[];
extern const unsigned char xdsExtraAlpha[][48 * 48];
extern const char *const xdsSpanish[][2];

int xdsLanguage = 1;

namespace {
const int kAsciiCells = 100; // NooDS's font: characters 32 to 131, 10 per row
const int kQuestion = '?' - 32;
}

std::string xdsText(const std::string &english) {
    if (xdsLanguage != 1) return english;
    static std::map<std::string, const char*> spanish;
    if (spanish.empty())
        for (int i = 0; xdsSpanish[i][0]; i++)
            spanish[xdsSpanish[i][0]] = xdsSpanish[i][1];
    std::map<std::string, const char*>::const_iterator found = spanish.find(english);
    return found == spanish.end() ? english : std::string(found->second);
}

int xdsGlyph(const std::string &text, uint32_t &i) {
    uint32_t code = (uint8_t)text[i];
    if (code >= 0xC0 && i + 1 < text.size() && ((uint8_t)text[i + 1] & 0xC0) == 0x80) {
        // UTF-8: two-byte characters cover Latin-1; longer ones are skipped as '?'.
        int extra = code >= 0xF0 ? 3 : code >= 0xE0 ? 2 : 1;
        code = extra == 1 ? ((code & 0x1F) << 6) | ((uint8_t)text[i + 1] & 0x3F) : '?';
        while (extra-- && i + 1 < text.size() && ((uint8_t)text[i + 1] & 0xC0) == 0x80) i++;
    }
    // Anything else above 0x7F is Latin-1, except 0x7F-0x83: the button icons.
    if (code >= 32 && code <= 0x83) return code - 32;
    for (int k = 0; k < xdsExtraCount; k++)
        if (xdsExtraCodes[k] == code) return kAsciiCells + k;
    return kQuestion;
}

int xdsGlyphWidth(int cell, const uint8_t *asciiWidths) {
    return cell < kAsciiCells ? asciiWidths[cell] : xdsExtraWidths[cell - kAsciiCells];
}

uint8_t *xdsFontBmp(uint8_t *bmp) {
    static uint8_t *font = 0;
    if (font) return font;
    // BMP: 0x46-byte header, then B,G,R,A pixels with the bottom row first.
    const int width = bmp[0x12] | (bmp[0x13] << 8), height = bmp[0x16] | (bmp[0x17] << 8);
    const int rows = (kAsciiCells + xdsExtraCount + 9) / 10;
    const int newHeight = rows * 48 > height ? rows * 48 : height;
    font = new uint8_t[0x46 + width * newHeight * 4];
    memcpy(font, bmp, 0x46);
    font[0x16] = newHeight & 0xFF;
    font[0x17] = newHeight >> 8;
    // The old picture keeps its place at the top; new rows start transparent white.
    memset(font + 0x46, 0, width * (newHeight - height) * 4);
    for (int p = 0; p < width * (newHeight - height); p++)
        font[0x46 + p * 4] = font[0x47 + p * 4] = font[0x48 + p * 4] = 0xFF;
    memcpy(font + 0x46 + width * (newHeight - height) * 4, bmp + 0x46, width * height * 4);
    for (int k = 0; k < xdsExtraCount; k++) {
        const int cell = kAsciiCells + k, left = 48 * (cell % 10), top = 48 * (cell / 10);
        for (int y = 0; y < 48; y++)
            for (int x = 0; x < 48; x++)
                font[0x46 + (((newHeight - 1 - (top + y)) * width + left + x) << 2) + 3] =
                    xdsExtraAlpha[k][y * 48 + x];
    }
    return font;
}
